def process(identity_theft_raw, new_england_states) -> pd.DataFrame:
    from glob import glob

    ne_states = set(new_england_states['Name'].tolist())

    # Map state names to file patterns
    all_files = glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv')

    results = []
    for fpath in all_files:
        fname = fpath.split('/')[-1].replace('.csv', '')
        if fname not in ne_states:
            continue

        # Read the raw file
        df = pd.read_csv(fpath, header=None, encoding='latin-1')

        # Find header row index
        for i, row in df.iterrows():
            vals = [str(v).strip() for v in row.values]
            if 'Metropolitan Area' in vals or any('Metropolitan Area' in str(v) for v in vals):
                header_row = i
                break
        else:
            continue

        # Data rows are after header
        for i in range(header_row + 1, len(df)):
            row = df.iloc[i]
            name_val = str(row.iloc[0]).strip()
            count_val = str(row.iloc[1]).strip() if len(row) > 1 else ''

            # Skip empty, NaN, or footer rows
            if not name_val or name_val.lower() in ('nan', '') or name_val.startswith('Source:'):
                continue
            if 'Statistical Area' not in name_val and 'Division' not in name_val:
                continue

            # Parse count
            try:
                count = int(str(count_val).replace(',', '').strip())
            except:
                continue

            results.append({'metro_area': name_val, 'reports': count, 'state': fname})

    return pd.DataFrame(results)

def load() -> pd.DataFrame:
    import glob, os
    results = []
    for state in ['New Hampshire', 'Rhode Island']:
        pattern = f"data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/{state}.csv"
        files = glob.glob(pattern)
        results.append({'state': state, 'files_found': str(files)})
        for f in files:
            with open(f, 'r', encoding='latin-1') as fh:
                content = fh.read()
            results.append({'state': state, 'files_found': f'CONTENT: {repr(content[:500])}'})
    return pd.DataFrame(results)

